insert into production_areas(organization_id,code,name,sequence)select id,x.code,x.name,x.sequence from organizations cross join(values('TUNNEL','Tunnel',30),('SCREEN','Screen Print',40),('DISPATCH','Dispatch',50))x(code,name,sequence)on conflict do nothing;
create table capacity_legacy_overrides(id uuid primary key default gen_random_uuid(),organization_id uuid not null references organizations(id),production_area_id uuid not null references production_areas(id),source_name text not null,daily_capacity numeric(14,3) not null check(daily_capacity>=0),work_days numeric(4,2) not null default 5 check(work_days between 0 and 7),temporary boolean not null default true,active boolean not null default true,created_at timestamptz not null default now(),unique(organization_id,production_area_id,source_name));
create table staffing_layouts(id uuid primary key default gen_random_uuid(),organization_id uuid not null references organizations(id),name text not null,effective_from date not null default current_date,effective_to date,active boolean not null default false,source text not null default'USER',created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(organization_id,name),check(effective_to is null or effective_to>=effective_from));
create table staffing_layout_lines(id uuid primary key default gen_random_uuid(),staffing_layout_id uuid not null references staffing_layouts(id)on delete cascade,production_area_id uuid not null references production_areas(id),shift_template_id uuid not null references shift_templates(id),day_of_week smallint check(day_of_week between 1 and 7),operator_count numeric(8,2) not null check(operator_count>=0),machine_count numeric(8,2) check(machine_count>=0),scheduled_hours numeric(5,2) not null check(scheduled_hours>0 and scheduled_hours<=24),hourly_rate numeric(12,3) check(hourly_rate>=0),efficiency numeric(6,4) check(efficiency between 0 and 1),created_at timestamptz not null default now());
create unique index staffing_layout_line_context on staffing_layout_lines(staffing_layout_id,production_area_id,shift_template_id,coalesce(day_of_week,0));
alter table capacity_legacy_overrides enable row level security;alter table staffing_layouts enable row level security;alter table staffing_layout_lines enable row level security;revoke all on capacity_legacy_overrides,staffing_layouts,staffing_layout_lines from anon,authenticated;grant select,insert,update,delete on capacity_legacy_overrides,staffing_layouts,staffing_layout_lines to service_role;
insert into capacity_legacy_overrides(organization_id,production_area_id,source_name,daily_capacity)select a.organization_id,a.id,'PCP Online active scenario 2026-09-09',x.capacity from production_areas a join(values('DTG',3952::numeric),('UP',2907::numeric),('DISPATCH',10640::numeric))x(code,capacity)on x.code=a.code on conflict do nothing;
insert into staffing_layouts(organization_id,name,active,source)select id,'Initial staffing example',true,'USER_EXAMPLE'from organizations on conflict do nothing;
insert into staffing_layout_lines(staffing_layout_id,production_area_id,shift_template_id,operator_count,scheduled_hours)select l.id,a.id,s.id,x.operators,s.scheduled_hours from staffing_layouts l join(values('Day','DTG',2::numeric),('Day','UP',2),('Day','TUNNEL',2),('Day','SCREEN',1),('Afternoon','DTG',2),('Afternoon','UP',3),('Afternoon','TUNNEL',2),('Afternoon','SCREEN',0),('Night','DTG',1),('Night','UP',0),('Night','TUNNEL',1),('Night','SCREEN',0))x(shift_name,area_code,operators)on true join production_areas a on a.organization_id=l.organization_id and a.code=x.area_code join shift_templates s on s.organization_id=l.organization_id and s.name=x.shift_name where l.name='Initial staffing example'on conflict do nothing;
create or replace view v_capacity_load with(security_invoker=true)as with demand as(select organization_id,line area_code,sum(remaining_units)demand_units from v_production_planning where coalesce(planning_status,'unplanned')not in('completed','cancelled')group by organization_id,line),profile_capacity as(select p.organization_id,a.code area_code,sum(p.resource_count*p.scheduled_hours*p.hourly_rate*p.efficiency)daily_capacity,sum(p.resource_count*p.scheduled_hours*p.hourly_rate*p.efficiency*p.work_days)weekly_capacity from capacity_profiles p join production_areas a on a.id=p.production_area_id where p.active group by p.organization_id,a.code),legacy_capacity as(select o.organization_id,a.code area_code,sum(o.daily_capacity)daily_capacity,sum(o.daily_capacity*o.work_days)weekly_capacity from capacity_legacy_overrides o join production_areas a on a.id=o.production_area_id where o.active group by o.organization_id,a.code),capacity as(select*from profile_capacity union all select l.*from legacy_capacity l where not exists(select 1 from profile_capacity p where p.organization_id=l.organization_id and p.area_code=l.area_code))select c.organization_id,c.area_code,coalesce(d.demand_units,0)demand_units,c.daily_capacity,c.weekly_capacity,case when c.daily_capacity=0 then null else round(coalesce(d.demand_units,0)/c.daily_capacity*100,2)end load_percent,c.daily_capacity-coalesce(d.demand_units,0)capacity_gap,case when c.daily_capacity=0 then null else round(coalesce(d.demand_units,0)/c.daily_capacity,2)end relative_lead_days from capacity c left join demand d using(organization_id,area_code);revoke all on v_capacity_load from anon,authenticated;grant select on v_capacity_load to service_role;
